fn count_uppercase(text: &Vec<char>) -> u64 {
    text.iter()
        .filter(|c| c.is_ascii_uppercase())
        .count() as u64
}

#[cfg(test)]
mod tests {
    use super::count_uppercase;

    #[test]
    fn empty() {
        let v: Vec<char> = vec![];
        assert_eq!(count_uppercase(&v), 0);
    }

    #[test]
    fn all_upper() {
        let v: Vec<char> = "HELLOWORLD".chars().collect();
        assert_eq!(count_uppercase(&v), 10);
    }

    #[test]
    fn mixed() {
        let v: Vec<char> = "Hello, World! 123 ABC xyz".chars().collect();
        // Uppercase letters are H, W, A, B, C
        assert_eq!(count_uppercase(&v), 5);
    }

    #[test]
    fn non_ascii() {
        let v: Vec<char> = "ÄÖÜßĀā".chars().collect();
        // None of these are ASCII uppercase A-Z
        assert_eq!(count_uppercase(&v), 0);
    }
}